class Record {
    private final String key;
    private final String value; // null value = tombstone (delete marker)
    private final long timestamp;
    Record(String key, String value, long timestamp) {
        this.key = key; this.value = value; this.timestamp = timestamp;
    }
    String getKey() { return key; }
    String getValue() { return value; }
    long getTimestamp() { return timestamp; }
    boolean isTombstone() { return value == null; }
    @Override public String toString() {
        return key + "=" + (value == null ? "<tombstone>" : value) + " @t" + timestamp;
    }
}

// ─── Would be in RetentionLog.java ───
class RetentionLog {
    private static final Logger log = Logger.getLogger(RetentionLog.class.getName());
    private final String topic;
    private final long retentionWindow;
    private final List<Record> records = new ArrayList<>();
    RetentionLog(String topic, long retentionWindow) {
        this.topic = topic; this.retentionWindow = retentionWindow;
    }
    void append(Record r) { records.add(r); }
    // Retention: drop records older than (now - window), ignoring keys
    void runRetention(long now) {
        long cutoff = now - retentionWindow;
        List<Record> kept = new ArrayList<>();
        for (Record r : records) {
            if (r.getTimestamp() >= cutoff) kept.add(r);
            else log.info(() -> "[" + topic + "] RETENTION deleted (too old) " + r);
        }
        records.clear(); records.addAll(kept);
        log.info(() -> "[" + topic + "] after retention keeps: " + records);
    }
}

// ─── Would be in CompactedLog.java ───
class CompactedLog {
    private static final Logger log = Logger.getLogger(CompactedLog.class.getName());
    private final String topic;
    private final List<Record> records = new ArrayList<>();
    CompactedLog(String topic) { this.topic = topic; }
    void append(Record r) { records.add(r); }
    // Compaction: keep only the LATEST record per key; tombstone removes the key
    void runCompaction() {
        Map<String, Record> latestByKey = new LinkedHashMap<>();
        for (Record r : records) latestByKey.put(r.getKey(), r); // later overwrites earlier
        List<Record> compacted = new ArrayList<>();
        for (Record r : latestByKey.values()) {
            if (r.isTombstone()) {
                log.info(() -> "[" + topic + "] COMPACTION key " + r.getKey()
                        + " deleted via tombstone");
            } else {
                compacted.add(r);
            }
        }
        log.info(() -> "[" + topic + "] after compaction keeps latest-per-key: " + compacted);
    }
}

