class Schema {
    private final int version;
    private final Set<String> fields;
    Schema(int version, Set<String> fields) { this.version = version; this.fields = fields; }
    int getVersion() { return version; }
    Set<String> getFields() { return fields; }
    // Backward compatible if it still contains all fields of the previous schema
    boolean isBackwardCompatibleWith(Schema previous) {
        return this.fields.containsAll(previous.getFields());
    }
    @Override public String toString() { return "v" + version + fields; }
}

// ─── Would be in SchemaRegistry.java ───
class SchemaRegistry {
    private static final Logger log = Logger.getLogger(SchemaRegistry.class.getName());
    private final Map<Integer, Schema> byId = new HashMap<>();
    private final Map<String, List<Schema>> bySubject = new HashMap<>();
    private int nextId = 1;
    // Register with BACKWARD compatibility enforcement
    int register(String subject, Schema schema) {
        List<Schema> history = bySubject.computeIfAbsent(subject, k -> new ArrayList<>());
        if (!history.isEmpty()) {
            Schema latest = history.get(history.size() - 1);
            if (!schema.isBackwardCompatibleWith(latest)) {
                log.severe(() -> "REJECT " + subject + " " + schema
                        + " — not backward compatible with " + latest
                        + " (would break existing consumers)");
                return -1;
            }
        }
        int id = nextId++;
        byId.put(id, schema);
        history.add(schema);
        log.info(() -> "REGISTERED " + subject + " " + schema + " as id=" + id);
        return id;
    }
    Schema getById(int id) { return byId.get(id); }
}

// ─── Would be in AvroLikeSerializer.java ───
class AvroLikeSerializer {
    private static final Logger log = Logger.getLogger(AvroLikeSerializer.class.getName());
    private final SchemaRegistry registry;
    AvroLikeSerializer(SchemaRegistry registry) { this.registry = registry; }
    // Wire format: [schemaId][compact values] — NO repeated field names like JSON
    byte[] serialize(String subject, int schemaId, Map<String, String> data) {
        Schema schema = registry.getById(schemaId);
        StringBuilder sb = new StringBuilder(schemaId + "|");
        for (String f : schema.getFields()) sb.append(data.getOrDefault(f, "")).append(",");
        log.info(() -> "SERIALIZE with schema id=" + schemaId
                + " -> wire=" + sb + " (field names NOT repeated on the wire)");
        return sb.toString().getBytes();
    }
}

// ─── Would be in TransferConsumer.java ───
class TransferConsumer {
    private static final Logger log = Logger.getLogger(TransferConsumer.class.getName());
    private final SchemaRegistry registry;
    TransferConsumer(SchemaRegistry registry) { this.registry = registry; }
    void consume(byte[] wire) {
        String msg = new String(wire);
        int schemaId = Integer.parseInt(msg.substring(0, msg.indexOf('|')));
        Schema schema = registry.getById(schemaId); // fetch exact schema by id
        String[] values = msg.substring(msg.indexOf('|') + 1).split(",");
        Map<String, String> decoded = new LinkedHashMap<>();
        int i = 0;
        for (String field : schema.getFields()) {
            decoded.put(field, i < values.length ? values[i] : "");
            i++;
        }
        log.info(() -> "DESERIALIZE using schema id=" + schemaId
                + " -> " + decoded + " (reliable, contract enforced)");
    }
}

